from series import *
start('استاد قاضی','ghazi',[('استافیلوکوک','ساختار، بیماری و افتراق'),('کلامیدیا','چرخه و تظاهر چشمی، تناسلی و تنفسی'),('مایکوپلاسما','بدون دیواره و پنومونی آتیپیک'),('سودوموناس و آسینتوباکتر','فرصت‌طلبی، بیماری و مقاومت')])
A(1,'شناخت استاف و روش‌های دسته‌بندی',[3,4], 'کاتالاز مسیر را جدا می‌کند؛ ظاهر خوشه‌ای به‌تنهایی نام گونه نیست.',[
 ['ویژگی پایه','کوکسی گرم مثبتِ خوشه‌ای؛ اورئوس در متن بی‌هوازی اختیاری و دارای کلنی محدب طلایی/زرد معرفی شده است.'],['سه گونه','اورئوس، اپیدرمیدیس و ساپروفیتیکوس؛ دو نام آخر عموماً کواگولاز منفی در مسیر درسی'],['کاتالاز','مثبت به سوی استاف؛ منفی به سوی استرپ در چارچوب جزوه'],['بایوتایپ','ویژگی‌های زیست‌شیمیایی مانند کاتالاز، مصرف مانیتول و نوکلئاز'],['سروتایپ و منشأ','واکنش آنتی‌ژنی؛ و منشأ جداسازی دو محور جدا هستند.'],['فاژتایپ','الگوی حساسیت به فاژ؛ ناحیهٔ شفاف شکل صفحهٔ ۴ علامت لیز است.'],['آنتی‌بیوتایپ و روش مولکولی','الگوی حساسیت دارویی با شناسایی قطعهٔ ژنتیکی یک چیز نیست؛ یک عامل می‌تواند چند برچسب همزمان داشته باشد.'] ],
 'خوشه و گرم، سپس کاتالاز و افتراق اختصاصی؛ هر روش یک محور دارد.',
 [('بایوتایپ، سروتایپ و فاژتایپ را مقایسه کنید.','اولی ویژگی زیست‌شیمیایی، دومی الگوی آنتی‌ژنی و سومی الگوی حساسیت به فاژ است؛ این دسته‌ها می‌توانند همپوشان باشند.',['سه معیار','همپوشانی']),('چرا کاتالاز همهٔ مسیر تشخیص نیست؟','در این درس شاخهٔ استاف/استرپ را جدا می‌کند؛ برای گونه به کواگولاز و آزمون‌های دیگر نیاز است.',['شاخه','گونه','آزمون همراه'])],warning=('نام‌گذاری و تعمیم','چارچوب Micrococcaceae و نام epidermis در منبع تاریخی/نامنظم است. رنگ‌آمیزی را با آزمون زیست‌شیمیایی یکی ندان؛ تاریخچهٔ نام کاشفان نیز بدون منبع روشن آمده است.'))
A(1,'ساختارها، آنزیم‌ها و سم‌های استاف',[4,5,6], 'نام عامل را به یکی از سه کار دفاع، گسترش یا آسیب وصل کن.',[
 ['کپسول و پروتئین A','کپسول با فرار از فاگوسیتوز؛ پروتئین A با برهم‌زدن کار پادتن در متن'],['پپتیدوگلیکان','پل پنج‌گلیسینی در استاف اورئوس، اسید تیکوئیک و پروتئین‌های سطحی ذکر شده‌اند.'],['کواگولاز و کاتالاز','اولی لختهٔ فیبرینی در شرح منبع؛ دومی تجزیهٔ پراکسید هیدروژن و حفاظت اکسیداتیو'],['گسترش','استافیلوکیناز تجزیهٔ فیبرین؛ هیالورونیداز اثر بر مادهٔ بین‌بافتی؛ نوکلئاز اثر بر اسید نوکلئیک؛ لیپاز اثر بر چربی'],['مقاومت','پنی‌سیلیناز زیرگروه بتالاکتاماز در روایت درس'],['سم‌ها','انتروتوکسین روده‌ای؛ اکسفولیاتیو/SSSS پوستی؛ TSST-1؛ سم سلولی شامل همولیزین و لوکوسیدین در فهرست'],['معیار اهمیت','صرف تعداد عوامل برابر شدت بیماری نیست؛ نقش و زمینه اهمیت دارد.'] ],
 'دفاع: کپسول و A؛ گسترش: تجزیهٔ سد؛ سم: اثر بر بافت هدف.',
 [('سه عامل گسترش را با هدفشان بنویسید.','هیالورونیداز با مادهٔ بین‌بافتی، استافیلوکیناز با فیبرین و نوکلئاز با اسید نوکلئیک مرتبط‌اند؛ این گسترش، حرکت تاژکی نیست.',['سه نام','هدف','گسترش از تحرک جدا']),('کپسول و پروتئین A چگونه متفاوت‌اند؟','در روایت متن کپسول تعامل با فاگوسیت و پروتئین A کار پادتن را مختل می‌کند؛ دو مسیر دفاعی‌اند.',['فاگوسیت','پادتن'])],warning=('ساختار و سم‌های مخلوط','صفحهٔ ۵ به جای مورامیک، نورآمینیک نوشته و بدون‌عارضه بودن مطلق داروی دیواره‌ای را نتیجه می‌گیرد؛ صفحهٔ ۶ TSST-1 را با سم پوستی یکی می‌کند. همچنین نبود کاتالاز در همهٔ بی‌هوازی‌ها و جبران‌پذیری همیشگی فقدان عامل مهم، تعمیم‌اند.'))
A(1,'بیماری استافی: سم غذایی یا عفونت بافتی',[6,7,8], 'مسمومیت با سم ازپیش‌ساخته را از ورود و تکثیر عامل جدا کن.',[
 ['غذایی','سمِ مقاوم نسبی در شرح جزوه، شروع کوتاه و برجستگی تهوع/استفراغ؛ نقش واگ ذکر شده است.'],['زردزخم','ضایعهٔ سطحی و دلمه؛ اورئوس و گاه استرپ در متن؛ تصویر صفحهٔ ۷ نمونهٔ ظاهر است.'],['فولیکول و پلک','فولیکولیت درگیری فولیکول؛ گل‌مژه نمونهٔ پلک؛ فورونکل و کاربونکل برای درگیری عمیق‌تر/پیوسته آمده‌اند.'],['اطراف ناخن و زخم','پارونیشیا؛ زخم و تروما و دیابت در زمینهٔ عفونت'],['دوردست','اندوکاردیت، پنومونی و استئومیلیت؛ در استخوان ورود مستقیم یا گسترش خونی دو مثال‌اند.'] ],
 'سم غذایی: اثر سم؛ زخم و خون: عامل و بافت. مو، پلک، ناخن را جدا نام ببر.',
 [('مسمومیت و عفونت غذایی چه فرقی دارند؟','در تعریف این جزوه، مسمومیت با سمِ دریافت‌شده رخ می‌دهد؛ عفونت با ورود عامل و فعالیت آن در بدن. کوتاهی شروع غذایی استاف به سم ازپیش‌ساخته مرتبط شده است.',['عامل ورودی','سم','زمان']),('استئومیلیت مستقیم و ثانویه را مقایسه کنید.','ورود عامل به استخوان در آسیب یا جراحی، مستقیم است؛ رسیدن از محل دیگر با خون، ثانویه در روایت متن.',['ورود مستقیم','خون','محل اولیه'])],warning=('احکام بیماری','عبارت «فقط استفراغ»، غالب‌بودن قارچ در همهٔ پارونیشیاها و تعریف چند جوش برای فورونکل نیاز به بررسی دارند. نام‌های ضایعه و عمق را با هم مخلوط نکن؛ شرح داروی موپیروسین در منبع، نسخهٔ همگانی این راهنما نیست.'))
A(1,'افتراق گونه و مقاومت استاف',[8,9,10], 'آزمایش‌ها باید به یک مسیر مقایسه‌ای تبدیل شوند.',[
 ['اورئوس در مسیر جزوه','کاتالاز مثبت، کواگولاز مثبت، DNase و مصرف مانیتول از سرنخ‌ها؛ همولیز به تنهایی قطعی نیست.'],['مانیتول‌سالت','نمک، انتخاب‌گری را توضیح می‌دهد؛ تخمیر و اسید، تغییر رنگ را. این دو اثر یکی نیستند.'],['نووبیوسین','ساپروفیتیکوس مقاوم؛ اپیدرمیدیس حساس، در مقایسهٔ دو گونهٔ جزوه'],['پیامد گونه‌ها','ساپروفیتیکوس با عفونت ادراری زن جوان؛ اپیدرمیدیس فلور پوست و عفونت وسیله/دریچهٔ مصنوعی'],['بتالاکتاماز و MRSA','تخریب دارو با مقاومت به متی‌سیلین یک مکانیسم واحد نیست؛ تعریف MRSA اورئوس مقاوم به متی‌سیلین است.'],['وانکومایسین','در متن برای موارد منتخب مطرح شده؛ اثر بر گرم مثبت و نگرانی مقاومت ذکر شده است.'] ],
 'اورئوس کواگولاز؛ دو منفی را با نووبیوسین مقایسه کن.',
 [('دو استاف کواگولاز منفی را چگونه مقایسه می‌کنید؟','ساپروفیتیکوس با عفونت ادراری زن جوان و مقاومت نووبیوسین؛ اپیدرمیدیس با فلور پوست، وسیلهٔ مصنوعی و حساسیت نووبیوسین در متن.',['محل','پیامد','آزمون']),('انتخاب‌گری محیط و تخمیر چه تفاوتی دارند؟','نمک رشد گروه‌ها را متفاوت می‌کند؛ مصرف مانیتول با تولید اسید نتیجهٔ افتراقی می‌دهد.',['نمک','قند','اسید'])],warning=('آزمایش و مقاومت','در آزمون کواگولاز «سرم» نوشته شده، در حالی که بحث لخته به مادهٔ زمینه وابسته است. افزودن کلاوولانات را با ساخت متی‌سیلین یکی ندان؛ شرح مقاومت فقط با جهش کروموزومی و عددهای تحمل محیطی هم نیاز به قید دارند.'))
A(2,'کلامیدیا: وابستگی به میزبان و دو شکل',[11,12,13,15], 'کلامیدیا باکتری است؛ وابستگی به سلول، آن را ویروس نمی‌کند.',[
 ['هویت','DNA و RNA و دستگاه ساخت پروتئین دارد؛ انگل اجباری درون‌سلولی و دارای اثر سلولی CPE در متن'],['ATP ترانسلوکاز؛ تأکید منبع','انتقال ATP میزبان در توضیح وابستگی انرژی برجسته است؛ ادعای ناتوانی مطلق ساخت انرژی نیاز به بررسی دارد.'],['جسم ابتدایی؛ EB','کوچک‌تر، کم‌فعال‌تر و آغازگر عفونت؛ در خارج سلول تکثیر نمی‌کند. شبیه‌سازی با اسپور فقط کمک توصیفی است.'],['جسم مشبک؛ RB','بزرگ‌تر و فعال‌تر در ساخت پروتئین و تقسیم داخل سلول'],['MOMP','پروتئین مهم پوشش خارجی، اتصال و تفاوت‌های آنتی‌ژنی در منبع'],['چرخه','اتصال و ورود EB، تبدیل به RB، تکثیر، تولید دوبارهٔ EB و خروج؛ همزمانی دو فرم در یک سلول ممکن است.'] ],
 'ابتدایی برای ورود؛ مشبک برای تکثیر؛ دوباره ابتدایی برای انتقال.',
 [('EB و RB را مقایسه کنید.','EB کوچک و آغازگر عفونت با فعالیت کمتر است؛ RB بزرگ‌تر و تکثیرشوندهٔ درون‌سلولی. خارج سلول تکثیر رخ نمی‌دهد.',['اندازه','نقش','جای تکثیر']),('چرخه را مرتب بنویسید.','اتصال با عامل سطحی، ورود EB، تبدیل به RB، تقسیم و سپس تبدیل بخشی به EB و خروج برای سلول دیگر.',['ورود','تبدیل','تکثیر','بازگشت و خروج'])],warning=('دیواره و اندازه','عدد فیلتر ۲۲ نانومتر، حدواسط باکتری–ویروس، نبود دیوارهٔ کلامیدیا/ریکتزیا، «تنها باکتری انتقال‌دهندهٔ ATP» و یکی‌گرفتن جسم ابتدایی مایکوپلاسما با کلامیدیا در متن ناسازگار یا مبهم‌اند.'))
A(2,'تراکوماتیس: چشم، عفونت تناسلی و نوزاد',[13,14,15,16,17], 'بی‌علامتی می‌تواند با آسیب همراه باشد؛ در مقایسه، سرووار و مسیر انتقال را کنار هم بنویس.',[
 ['A، B و C','تراخم و انتقال ترشحات چشمی؛ سطح بهداشت در منبع برجسته است.'],['D تا K','عفونت تناسلی و امکان انتقال هنگام تولد با کونژکتیویت یا پنومونی نوزاد؛ هر عفونت چشمی نوزاد تراخم نیست.'],['LGV','گروه بیماری تناسلی دیگر در فهرست؛ نام LGV را با همهٔ D–K یکی نکن.'],['بالارونده','سرویکس، رحم و لوله‌ها در زنان؛ مجرا، پروستات و اپیدیدیم در مردان در روایت منبع'],['پیامدها','سرویسیت/اورتریت، درد لگن، PID، ناباروری، حاملگی خارج رحم و پیامد بارداری در فهرست'],['STI و STD','عفونت از بیماری علامت‌دار گسترده‌تر است؛ عنوان اپیدمی خاموش و رقم ۷۰٪ بی‌علامتی بدون جمعیت دقیق در متن آمده است.'],['SAFE','جراحی، آنتی‌بیوتیک، پاکیزگی صورت و بهبود محیط؛ نام راهبرد مطرح‌شدهٔ تراخم'] ],
 'A–C چشم؛ D–K تناسلی و نوزاد؛ بی‌علامتی را برابر بی‌آسیبی ندان.',
 [('چرا عفونت نوزاد را تراخم نمی‌نامیم؟','در جزوه انتقال D–K هنگام تولد با کونژکتیویت/پنومونی جدا از تراخم A–C است؛ محل چشم به تنهایی نام سرووار یا بیماری را تعیین نمی‌کند.',['سرووار','راه','چشم کافی نیست']),('عفونت بالارونده چه پیامدی دارد؟','گسترش از مخاط تحتانی به سرویکس و لوله‌ها می‌تواند با التهاب، آسیب و ناباروری یا حاملگی خارج رحم مرتبط شود؛ در مردان مجرا و اپیدیدیم مطرح‌اند.',['مسیر','التهاب','پیامد'])],warning=('ادعا و توصیهٔ نوزادی','سرطان سرویکس/تخمدان به‌عنوان پیامد قطعی، عدد بی‌علامتی همگانی و توصیه‌های متناقض قطرهٔ چشمی/داروی پیشگیری نوزاد نیاز به بررسی دارند؛ این بخش دستور درمان نیست.'))
A(2,'گونه‌های تنفسی و تشخیص کلامیدیا',[14,15,16,17,18], 'وابستگی به سلول، نوع نمونه و آزمون را توضیح می‌دهد؛ نتیجهٔ سرولوژی را با اثبات علت یکی نکن.',[
 ['تراکوماتیس در جدول','میزبان انسان؛ کونژکتیویت، پنومونی نوزاد، عفونت تناسلی و LGV؛ انکلوزیون گلیکوژن‌دار و حساسیت سولفونامیدی «مثبت» در جدول'],['پسیتاسی','پرندگان و نیز دام/گربه در جدول؛ پنومونی و اندوکاردیت؛ دو ویژگی گلیکوژن و سولفونامید «منفی» در همان جدول'],['پنومونیه؛ TWAR','انسان؛ برونشیت و پنومونی؛ گلیکوژن و حساسیت یادشده منفی؛ آترواسکلروز با علامت سؤال در تصویر'],['اصل تشخیص','عامل داخل سلول است؛ شواهد سلولی/مولکولی از پادتن تماس قبلی جدا می‌شوند. سلول McCoy و مدل‌های نام‌برده در جزوه، توضیح وابستگی‌اند.'],['مقایسهٔ پنومونی','در روایت جزوه تیپیک ناگهانی و با خلط برجسته؛ آتیپیک تدریجی‌تر و با سرفهٔ خشک مطرح می‌شود.'] ],
 'پسیتاسی و پرنده؛ پنومونیه و تنفس؛ تراکوماتیس و چشم/تناسلی.',
 [('سه گونه را با میزبان و بیماری مقایسه کنید.','تراکوماتیس انسان و چشم/تناسلی/نوزاد؛ پسیتاسی پرنده و زئونوز تنفسی؛ پنومونیه انسان و بیماری تنفسی.',['سه نام','میزبان','محل']),('چرا پادتن برای نسبت‌دادن آترواسکلروز کافی نیست؟','تماس، واکنش متقاطع و همبستگی از علت‌بودن جدا هستند؛ خود جدول رابطه را با سؤال مطرح می‌کند.',['همبستگی','واکنش متقاطع','علت'])],warning=('تعمیم تشخیص و پنومونی','قاطعیت گلیکوژن/CPE به تنهایی، بی‌ارزش‌بودن مطلق همهٔ سرولوژی‌ها، قرار دادن کلبسیلا در همهٔ آتیپیک‌ها و خفیف‌بودن همیشگی پنومونی آتیپیک نیاز به بررسی دارند.'))
A(3,'مایکوپلاسما: نبود دیواره و گونه‌های مهم',[19,20,21], 'نبود دیواره، هم ظاهر و هم انتخاب هدف دارویی را تغییر می‌دهد.',[
 ['ساختار','بدون دیوارهٔ پپتیدوگلیکانی، چندشکلی، غشای دارای استرول و ژنوم کوچک در چارچوب متن'],['تفاوت با کلامیدیا','وابستهٔ اجباری درون‌سلولی معرفی نشده و امکان رشد مستقل روی محیط مناسب در شرح جزوه دارد؛ PPLO نام برده شده است.'],['پنومونیه','راه تنفسی فوقانی/تحتانی، پنومونی آتیپیک و تجمع در فضای بسته/مدرسه'],['هومینیس و ژنیتالیوم','محل ادراری–تناسلی؛ تب پس از زایمان و PID در فهرست؛ وضعیت انتقال جنسی در متن ناسازگار است.'],['پنترانس','ارتباط با HIV به صورت ادعا در متن/جدول، نه اثبات رابطهٔ یک‌طرفه'],['اوره‌آپلاسما اوره‌آلیتیکوم','نیاز به اوره و اورتریت غیرگنوکوکی؛ در جدول شیوع «بسیار شایع» نوشته شده است.'],['درخت صفحهٔ ۲۰','ردهٔ Mollicutes، راستهٔ Mycoplasmatales؛ Mycoplasmataceae شامل Mycoplasma و Ureaplasma؛ شاخه‌های گیاهی Spiroplasmataceae و حیوانی Acholeplasmataceae و Anaeroplasmataceae هم در شکل آمده‌اند.'] ],
 'دیواره نیست: شکل ثابت و هدف دیواره‌ای هم نیست؛ غشای استرولی را به خاطر بسپار.',
 [('چرا بتالاکتام برای این بحث هدف مناسبی ندارد؟','مایکوپلاسما دیوارهٔ پپتیدوگلیکانی ندارد؛ پس داروی هدف‌گیرندهٔ آن ساختار، هدف معمول خود را در این عامل ندارد.',['نبود ساختار','هدف دارو']),('تفاوت اصلی با کلامیدیا چیست؟','در متن، کلامیدیا تکثیر وابسته به سلول زنده دارد؛ مایکوپلاسما بدون دیواره است ولی تکثیر مستقل در شرایط تغذیه‌ای مناسب ممکن است.',['درون‌سلولی','دیواره','تکثیر'])],warning=('تعمیم مایکوپلاسما','«تنها باکتری دارای استرول»، کوچک‌ترین ژنوم در همهٔ باکتری‌ها، نبود انتقال جنسی ژنیتالیوم و ارتباط علّی قطعی با سقط/HIV نیاز به بررسی دارند؛ ادعای معدوم‌سازی همهٔ طیور نیز خارج از توضیح این درس و بدون زمینه است.'))
A(3,'پنومونی آتیپیک و آزمون سرد',[18,20,21], 'ویژگی بالینی سرنخ است؛ آزمون‌های مختلف یک چیز را نمی‌سنجند.',[
 ['بالینی','تب، علائم تنفسی و سرفهٔ خشک با شروع تدریجی در شرح پنومونی آتیپیک؛ راه‌رفتن بیمار به معنی کم‌خطر بودن همهٔ موارد نیست.'],['مولکولی','وجود مادهٔ ژنتیکی عامل؛ در جزوه PCR برجسته شده است.'],['سرولوژی','پاسخ پادتنی و سابقهٔ تماس می‌تواند تفسیر را پیچیده کند؛ رد همهٔ کاربردها تعمیم است.'],['آگلوتیناسیون سرد','پادتن IgM و تجمع گلبول قرمز وابسته به دما در شکل؛ تجمع را با لختهٔ فیبرینی یکی نکن.'],['دارو در متن','ماکرولیدها مانند اریترومایسین/آزیترومایسین و تتراسایکلین برای هدف ساخت پروتئین نام برده شده‌اند؛ الگوریتم تجویز نیست.'] ],
 'مولکولی، ژن را؛ سرولوژی، پاسخ را؛ آزمون سرد، تجمع را نشان می‌دهد.',
 [('آزمون سرد چه پدیده‌ای را نشان می‌دهد؟','تجمع گلبول قرمز به واسطهٔ پادتن مرتبط با دما؛ خودِ دیدن میکروب یا لخته‌شدن فیبرینی نیست و به تنهایی تشخیص اختصاصی کامل نمی‌دهد.',['IgM','تجمع','محدودیت']),('چرا فقط تابلوی تیپیک/آتیپیک کافی نیست؟','الگوها همپوشانی دارند؛ تشخیص عامل به زمینه و شواهد اختصاصی نیاز دارد، نه فرض خفیف یا شدیدبودن اجباری.',['همپوشانی','عامل','شواهد'])],warning=('اختصاصیت آزمون سرد','صفحهٔ ۲۱ تجمع را معادل ابتلا و «لختگی» می‌نامد؛ تجمع گلبول و اختصاصیت یک گونه از متن به تنهایی ثابت نمی‌شوند.'))
A(4,'سودوموناس: هویت، رنگدانه و جدول‌های منبع',[23,24], 'رنگ و اکسیداز سرنخ‌اند؛ منشأ محیطی و فرصت‌طلبی را فراموش نکن.',[
 ['هویت','باسیل گرم منفی، هوازی و متحرک با تاژک قطبی؛ اکسیداز مثبت در افتراق درسی با انتروباکتری‌ها'],['محیط','آب و خاک و ناحیهٔ مرطوب؛ فرصت‌طلب و عامل مهم بیمارستانی؛ کلنی از خشک/خشن تا موکوئید متفاوت است.'],['پیووردین','زرد و فلورسنت در شرح تشخیصی'],['پیوسیانین','آبی/سبزآبی؛ اثر بر دفاع مژکی در روایت متن؛ ترکیب رنگدانه‌ها به سبزی نسبت داده شده است.'],['بو و همولیز','بوی میوه‌ای/انگور ترش و همولیز متغیر، سرنخ توصیفی‌اند.'] ],
 'باسیل و اکسیداز؛ محیط مرطوب؛ زرد فلورسنت و آبی را جدا نام ببر.',
 [('دو رنگدانه را مقایسه کنید.','پیووردین زرد و با فلورسانس تشخیصی مطرح است؛ پیوسیانین آبی/سبزآبی و با آسیب دفاع مژکی ربط دارد.',['نام','رنگ','نقش']),('چرا صرف رنگ کافی نیست؟','ظاهر کلنی متغیر است و سرنخ باید با گرم، شکل، اکسیداز و زمینه تفسیر شود.',['تغییرپذیری','ویژگی همراه'])],more=D('تمام گروه‌های جدول rRNA صفحهٔ ۲۳',T(['گروه','نام‌ها با نگارش منبع'],[['I فلورسنت','P. aeruginosa، P. fluorescens، P. putida'],['I غیرفلورسنت','P. stutzeri، P. mendocina'],['II','Burkholderia pseudomallei، B. mallei، B. cepacia، Cupriavidus، Delftia، Pandoraea، Ralstonia pickettii'],['III','Comamonas و Acidovorax'],['IV','Brevundimonas'],['V','Stenotrophomonas maltophilia']]))+D('جدول اولویت مقاومت در خود جزوه',T(['رده در تصویر','موارد'],[['بحرانی','آسینتوباکتر بومانی و سودوموناس مقاوم به کارباپنم؛ انتروباکتریاسه مقاوم به کارباپنم/سفالوسپورین'],['بالا','انتروکوک فسیوم مقاوم به وانکومایسین؛ اورئوس مقاوم متی‌سیلین/وانکومایسین؛ هلیکوباکتر مقاوم کلاریترومایسین؛ کمپیلوباکتر و سالمونلا مقاوم فلوروکینولون؛ گنوکوک مقاوم سفالوسپورین/فلوروکینولون'],['متوسط','پنوموکوک غیرحساس به پنی‌سیلین؛ هموفیلوس مقاوم آمپی‌سیلین؛ شیگلا مقاوم فلوروکینولون']])) ,warning=('چارچوب تاریخی','جدول اولویت و گروه‌بندی rRNA همان تصویر منبع‌اند و فهرست روز معرفی نشده‌اند. عدد ۲۴ در استخراج برای دما در تصویر ۴۲ است؛ به جای حفظ عدد وارونه، ارجاع تصویری را ملاک قرار بده.'))
A(4,'سودوموناس: میزبان و محل‌های بیماری',[25,26], 'سوختگی، وسیله و مخاط آسیب‌دیده، فرصت ورود و استقرار را می‌سازند.',[
 ['افراد در خطر','سوختگی، دیابت و زخم، سالمندی، بستری، نقص ایمنی و سیستیک‌فیبروزیس در منبع؛ واژهٔ «پارتومکی» مبهم است.'],['چشم','کراتیت، هیپوپیون و پان‌افتالمیت؛ لنز/آسیب قرنیه در مثال و اهمیت پیشرفت سریع'],['گوش','گوش خارجی و شکل‌های شدیدتر؛ فرد مستعد و محیط آب در متن'],['خون و پوست','باکتریمی و اکتیمای گانگرنوزوم؛ شکل صفحهٔ ۲۶ نمای آسیب پوستی را نشان می‌دهد.'],['قلب و ادرار','اندوکاردیت و وسایل/دریچه؛ UTI با زمینهٔ کاتتر و بیمارستان'],['ریه','عفونت جامعه یا بیمارستان؛ CF و مخاط غلیظ، کاهش پاک‌سازی و استقرار'],['استخوان و گوارش','ورود مستقیم/انتشار خونی؛ تب شانگهای در سن پایین، با تأکید پرسش گذشته در منبع'] ],
 'سد آسیب‌دیده، پاک‌سازی ضعیف و وسیلهٔ خارجی؛ محل، پیامد را تعیین می‌کند.',
 [('چرا سوختگی و CF هر دو زمینه‌سازند؟','سوختگی سد پوست را برمی‌دارد؛ CF پاک‌سازی راه هوایی را مختل و مخاط غلیظ را به زمینهٔ استقرار تبدیل می‌کند؛ دو مسیر متفاوتِ فرصت‌طلبی‌اند.',['پوست','مخاط','دو مسیر']),('باکتریمی و ضایعهٔ پوستی چگونه مرتبط‌اند؟','در متن، حضور عامل در خون می‌تواند با ضایعهٔ اکتیمای گانگرنوزوم همراه شود؛ خود باکتریمی را با هر راش یکسان نمی‌کنیم.',['خون','نام ضایعه','قید'])],warning=('تعمیم خطر','نفی عفونت گوش در سالم، ضروری دانستن یک ریسک ثابت برای همهٔ UTIها و یکی‌گرفتن هر باکتریمی با علت اندوکاردیت، ادعاهای بیش‌ازحد کلی‌اند.'))
A(4,'توان بیماری‌زایی و مقاومت سودوموناس',[27,28,29], 'اتصال، فرار دفاعی، آسیب و مقاومت را چهار ستون مستقل بخوان.',[
 ['اتصال','پیلی، تاژک و عوامل غیرپیلی؛ آلژینات در شرح کپسول/ماتریکس به اتصال و حفاظت مرتبط است.'],['فرار از دفاع','پیوسیانین و اختلال مژک؛ آلکالین پروتئاز و اثر بر کمپلمان'],['LPS','IL-1، IL-6 و TNF-α در روایت التهاب، تب و اختلال عروقی'],['اگزوتوکسین A','قسمت اتصال و قسمت فعال؛ اختلال EF2 و توقف ساخت پروتئین در شرح منبع؛ اگزوتوکسین S نیز نام برده شده است.'],['آنزیم‌ها','LasA، LasB، الاستاز و فسفولیپاز؛ تخریب بافت/عروق و غشا در متن'],['مقاومت','نفوذ کم، پمپ خروج دارو و آنزیم غیرفعال‌کننده؛ ذاتی و اکتسابی می‌توانند همراه باشند.'],['آنتی‌بیوگرام','برای انتخاب متناسب اهمیت دارد؛ نام درمان تجربی در متن به فوریت بالینی مربوط است، نه نسخهٔ ثابت.'] ],
 'ورود کم، خروج زیاد و داروی تخریب‌شده؛ سم A را به EF2 وصل کن.',
 [('سه محور مقاومت را شرح دهید.','دارو کمتر وارد می‌شود، با پمپ بیرون رانده می‌شود یا توسط آنزیم غیرفعال می‌گردد. این‌ها از آسیب ناشی از سم جدا هستند.',['نفوذ','خروج','غیرفعال‌سازی']),('سم A چگونه آسیب می‌دهد؟','اتصال به سلول و اثر بخش فعال بر EF2، ساخت پروتئین را مختل می‌کند و به آسیب/مرگ سلول ربط دارد.',['اتصال','EF2','پروتئین'])],more=D('فهرست داروییِ آموزشی صفحهٔ ۲۹',P('رمز CAMP FIRE در منبع برای کارباپنم، آمینوگلیکوزید، مونوباکتام، پلی‌میکسین، فلوروکینولون، سفالوسپورین و پنی‌سیلین وسیع‌الطیف آمده است؛ مثال‌ها: ایمیپنم/مروپنم/دوریپنم، کانامایسین/جنتامایسین/توبرامایسین، آزترئونام، کلیستین، سیپروفلوکساسین/لووفلوکساسین، سفتازیدیم/سفپیم و پیپراسیلین/تیکارسیلین. سفیدروکول و مهارکننده‌های بتالاکتاماز هم نام برده شده‌اند. همه، فهرست همان جزوه‌اند و فعالیت همگانی علیه هر جدایه را ثابت نمی‌کنند.')),warning=('نام آنزیم و دارو','نام‌گذاری LasA/LasB، گروه‌های شیمیایی آنزیم اصلاح‌کنندهٔ آمینوگلیکوزید، شرح سفیدروکول به صورت محروم‌کردن ساده از آهن، بی‌اهمیت دانستن رلباکتام و ادعای موجودنبودن دارو در ایران نیاز به بررسی دارند؛ پژوهش بیرونی انجام نشده است.'))
A(4,'آسینتوباکتر و پیشگیری بیمارستانی',[29,30], 'شباهت فرصت‌طلبی، تفاوت آزمون‌ها را از بین نمی‌برد.',[
 ['شباهت','گرم منفی، هوازی، کاتالاز مثبت و مقاومت بالا در متن؛ عوامل فرصت‌طلب بیمارستانی'],['افتراق','آسینتوباکتر کوکوباسیل و اکسیداز منفی؛ سودوموناس باسیل و اکسیداز مثبت در جدول درسی'],['گونه‌ها','بومانی و لوفی در منبع برجسته‌اند؛ تعداد ثابت گونه‌ها و نسبت‌ها را دادهٔ تاریخی جزوه بدان.'],['محیط و وسایل','سطوح، دست و تجهیزات مانند ونتیلاتور/دیالیز؛ تماس و انتقال زنجیره‌ای مهم‌اند.'],['نام محیط‌ها','کروم‌آگار و لیدز برای بحث آسینتوباکتر؛ ستریماید برای سودوموناس در منبع؛ اصل انتخاب/افتراق مهم است.'],['اصول کنترل','بهداشت دست، رسیدگی به محیط و وسیله و مصرف سنجیدهٔ آنتی‌بیوتیک در متن'],['داروهای نام‌برده','ایمیپنم، پلی‌میکسین، تایجی‌سایکلین و برخی آمینوگلیکوزیدها؛ انتخاب وابسته به حساسیت، نه دستور واحد'] ],
 'آسینتو: کوکوباسیل، اکسیداز منفی؛ هر دو در زنجیرهٔ بیمارستان مهم‌اند.',
 [('دو عامل را در سه محور مقایسه کنید.','هر دو گرم منفی و فرصت‌طلب بیمارستانی‌اند؛ سودوموناس باسیل و اکسیداز مثبت، آسینتوباکتر کوکوباسیل و اکسیداز منفی است؛ مقاومت در هر دو اهمیت دارد.',['شباهت','شکل','اکسیداز']),('چرا کنترل فقط انتخاب یک دارو نیست؟','انتقال با دست، محیط و تجهیزات و انتخاب مقاومت نیز نقش دارند؛ بهداشت و مدیریت مصرف کنار درمان قرار می‌گیرند.',['انتقال','تجهیزات','مصرف دارو'])],warning=('عبارت نامفهوم','«گایرلوتایپ یا کلاژن ندارد» در صفحهٔ ۳۰ روشن نیست. بیماری‌های کاملاً یکسان، تنها دو گونهٔ مهم و توان گرمایی یکسان همهٔ جدایه‌ها نیز تعمیم‌اند.'))
mixed=[Q('یک کوکسی گرم مثبت را در مسیر استافی چگونه بررسی می‌کنید؟','شکل و گرم، کاتالاز و سپس کواگولاز؛ برای دو گونهٔ منفی، مقایسهٔ نووبیوسین و زمینهٔ بالینی در این جزوه مطرح است.',['گرم','کاتالاز','کواگولاز','افتراق'],[3,8,9]),Q('کلامیدیا و مایکوپلاسما را از نظر دیواره، وابستگی و درمان مفهومی مقایسه کنید.','کلامیدیا تکثیر درون‌سلولی و دو فرم دارد؛ مایکوپلاسما بدون دیواره و فاقد الزام همان تکثیر داخل سلول است. نبود پپتیدوگلیکان هدف داروی دیواره‌ای را حذف می‌کند؛ ادعاهای مطلق دیوارهٔ کلامیدیا در منبع علامت دارند.',['دیواره','تکثیر','فرم','هدف'],[11,12,13,19,21]),Q('چرا ظاهر مشابه عفونت، درمان یکسان را ثابت نمی‌کند؟','عامل، محل، میزبان و حساسیت متفاوت‌اند؛ نمونهٔ این فایل پنومونی‌های با عوامل مختلف و دو فرصت‌طلب بیمارستانی‌اند.',['عامل','میزبان','حساسیت'],[18,21,26,29,30]),Q('گسترش بافتی، حرکت و مقاومت را تفکیک کنید.','گسترش با تجزیهٔ سد ممکن می‌شود؛ حرکت به ساختاری مانند تاژک مربوط است؛ مقاومت با نفوذ/خروج/تخریب دارو. این سه اصطلاح مترادف نیستند.',['سه تعریف','مثال متناسب'],[6,27,28])]
source=[Q('چرا کلامیدیا انگل اجباری درون‌سلولی معرفی می‌شود؟','پاسخ کوتاه منبع وابستگی انرژی به میزبان است؛ این راهنما آن را شرح وابستگیِ همان جزوه می‌داند و ناتوانی مطلق هر متابولیسم را قطعی نمی‌کند.',['میزبان','انرژی','قید'],[11],'پرسش صریح جزوه'),Q('چگونه از ATP میزبان استفاده می‌کند؟','پاسخ خود منبع ATP ترانسلوکاز است؛ نام انتقال‌دهنده را از نقش عامل چسبندگی MOMP جدا بنویس.',['ترانسلوکاز','انرژی','تفکیک اتصال'],[11],'پرسش صریح جزوه')]
